/* Einfuhr (erzeugt von Entwickler-Tools/module.mjs, nicht von Hand ändern) */
import { $, _hlpT, _hlpUeber, lang, setze_hlpT, setze_hlpUeber, t } from './30-kern.js';
import { activePreset, setzeActivePreset } from './33-export-stapel.js';
import { renderUserPresets, saveUserPresets, userPresets } from './34-hdr-panorama.js';
/* Ende Einfuhr */
(function(){
  const wrap=$('userPresets'); if(!wrap) return;
  const LP=400, MOVE=8;
  let timer=0, row=null, pid=0, startX=0, startY=0, curX=0, curY=0, active=false, justDragged=false;
  let rows=[], baseTop=[], h=0, stride=0, from=0, to=0, grabY=0, rowLeft=0, rowW=0;
  function detach(){ clearTimeout(timer); timer=0;
    window.removeEventListener('pointermove',onMove,true);
    window.removeEventListener('pointerup',onUp,true);
    window.removeEventListener('pointercancel',onCancel,true); }
  function reset(){ detach(); row=null; active=false; rows=[]; }
  function onDown(e){
    if(e.button!=null && e.button!==0) return;
    const r=e.target.closest&&e.target.closest('.userPreset'); if(!r||!wrap.contains(r)) return;
    if(e.target.closest('.iconbtn')) return;
    row=r; pid=e.pointerId; startX=curX=e.clientX; startY=curY=e.clientY; active=false;
    window.addEventListener('pointermove',onMove,true);
    window.addEventListener('pointerup',onUp,true);
    window.addEventListener('pointercancel',onCancel,true);
    clearTimeout(timer); timer=setTimeout(begin, LP);
  }
  function begin(){ if(!row) return; timer=0;
    rows=[...wrap.querySelectorAll('.userPreset')]; from=rows.indexOf(row); if(from<0){ reset(); return; }
    baseTop=rows.map(x=>x.getBoundingClientRect().top);
    const rr=row.getBoundingClientRect(); h=rr.height; rowLeft=rr.left; rowW=rr.width;
    stride = rows.length>1 ? (baseTop[1]-baseTop[0]) : (h+6);
    grabY = startY-baseTop[from]; to=from; active=true;
    rows.forEach(x=>{ if(x!==row) x.style.transition='transform .18s ease'; });
    row.style.transition='none'; row.classList.add('dragging');
    try{ if(navigator.vibrate) navigator.vibrate(8); }catch(_){}
    update();
  }
  function update(){
    const wr=wrap.getBoundingClientRect();
    const dx=Math.max(wr.left-rowLeft, Math.min(wr.right-(rowLeft+rowW), curX-startX));
    row.style.transform=`translate(${dx}px,${curY-startY}px) scale(1.03)`;
    const dragCenter=(curY-grabY)+h/2;
    let t=0; for(let i=0;i<rows.length;i++){ if(i===from) continue; if(dragCenter>baseTop[i]+h/2) t++; }
    to=Math.max(0,Math.min(rows.length-1,t));
    rows.forEach((x,i)=>{ if(i===from) return; const j=i<from?i:i-1, slot=j<to?j:j+1; x.style.transform=`translateY(${(slot-i)*stride}px)`; });
  }
  function onMove(e){ if(e.pointerId!==pid) return; curX=e.clientX; curY=e.clientY;
    if(!active){ if(Math.abs(curX-startX)>MOVE||Math.abs(curY-startY)>MOVE) reset(); return; }
    e.preventDefault(); update(); }
  function onUp(e){ if(e.pointerId!==pid) return;
    if(!active){ reset(); return; }
    e.preventDefault();
    const f=from, tt=to, r=row, st=stride, bt=baseTop;
    justDragged=true; setTimeout(()=>{ justDragged=false; }, 60);
    r.style.transition='transform .16s ease'; r.style.transform=`translateY(${(bt[0]+tt*st)-bt[f]}px)`;
    detach(); row=null; active=false; rows=[];
    setTimeout(()=>commit(f,tt), 160);
  }
  function onCancel(e){ if(e.pointerId!==pid) return; if(active){ rows.forEach(x=>{ x.style.transition=''; x.style.transform=''; }); if(row){ row.classList.remove('dragging'); row.style.transition=''; row.style.transform=''; } } reset(); }
  function commit(f,tt){
    if(f===tt){ renderUserPresets(); return; }
    const arr=userPresets(); if(f<0||f>=arr.length){ renderUserPresets(); return; }
    const [it]=arr.splice(f,1); arr.splice(tt,0,it); saveUserPresets(arr);
    const m=/^u:(\d+)$/.exec(activePreset||'');
    if(m){ let k=+m[1]; if(k===f) k=tt; else { k=k>f?k-1:k; k=k>=tt?k+1:k; } setzeActivePreset('u:'+k); }
    renderUserPresets();
  }
  wrap.addEventListener('pointerdown',onDown,true);
  wrap.addEventListener('click',e=>{ if(justDragged){ e.preventDefault(); e.stopPropagation(); } },true);
})();
